//! Collection help belongs to this plugin package, never to the host's GUI.
use herbert_contract::HelpSection;

pub(super) fn sections(category: &str) -> Vec<HelpSection> {
    let mut sections = Vec::new();
    let mut add = |title: &str, paragraph: &str| {
        sections.push(HelpSection {
            title: title.into(),
            paragraphs: vec![paragraph.into()],
        })
    };
    match category {
        "menus-and-launch-definitions" => add("Menu selection and required ancestors", "Menu ID starts with is a literal, case-sensitive native MenuID prefix. Spaces, punctuation and Unicode stay unchanged; blank selects all eligible menus. Custom menu files and rows in system snapshots follow this selection. Required authorized custom ancestors retain complete original source and native XML even outside the prefix, with dependency roles distinct from prefix-matched roots. One physical artifact can have both roles; retained roots are not fetched again to establish ancestor membership. Physical Company+MenuID deduplication keeps shared ancestors once; parents precede children in restore guidance. Existing system parents remain target prerequisites. Descendants and unrelated branches are not selected. Native pages validate before selection and continue through empty matches. Exact row/revision witnesses bind late ancestor body reads; missing, changed, unauthorized or ambiguous parents and relevant cycles leave closure incomplete while useful selected output remains. Acquired structural/XML errors remain visible even on excluded rows. Exact Company+MenuID acquisition ignores the prefix. Matching contract: menus-and-launch-definitions-menu-id-prefix-v1."),
        "searches-and-navigation" => add("Search and navigation selection", "Definition family selects all existing families by default, or Quick, Predictive, Named, Enterprise, saved context XML or legacy context graphs. Quick and Predictive use the native IsPredictive flag. Search ID starts with is a literal, case-sensitive QuickSearchID, NSId or SearchID prefix for the four search families only. Spaces, punctuation and Unicode remain unchanged; blank selects all eligible search IDs. Both context-menu families are independent of this prefix; it stays saved when switching families. Named and Enterprise reads are narrowed to IDs starting with the prefix text before any %, _, [, ] or non-ASCII character; the literal prefix is applied locally. Page structure and parent/child ownership still validate for every returned row. Acquired graph child-read failures and existing saved Content, length and child-structure checks become identity-bound diagnostics only for selected records, or records whose flag or ID cannot be read. Excluded records are neither validated nor reported. Valid selected peers remain intact. Complete selected criteria, value lists, controls, clauses, fields, XML/chunks and legacy children stay together. Diagnostics and incomplete coverage from selected records and source failures remain even on empty selected pages; raw paging and source transitions continue. A diagnostic-only QuickSearch identity without a validated IsPredictive flag is not guessed into a restricted family. Exact composite acquisition ignores both discovery settings. Matching contracts: searches-and-navigation-definition-family-v1 and searches-and-navigation-search-id-prefix-v1."),
        "kinetic-applications-and-layers" => add("Kinetic application selection", "Application ID starts with is a literal, case-sensitive complete ViewId prefix. Spaces, punctuation and Unicode remain unchanged. Blank selects all eligible applications. Herbert validates acquired metadata before selecting whole applications and applying batch or history offsets. Every selected layer, required parent, saved draft, resource and requested revision stays with its application. Empty selected metadata pages follow raw native continuation. Exact application-bundle retrieval ignores the prefix. Matching contract: kinetic-applications-and-layers-application-id-prefix-v1."),
        "kinetic-personalizations" => add("Kinetic personalization owner selection", "User ID starts with is a literal, case-sensitive native personal-owner prefix. Spaces, punctuation and Unicode remain unchanged. Blank selects all eligible personal owners and standalone shared layouts. A nonblank prefix excludes ownerless shared layouts as standalone records; required shared bases and original image bytes still accompany selected owners. Grid layouts use Key1, KNTCPersLayer records use SysCharacter02, and home, options and favorites use UserID. Full acquired pages validate before selection in separate and combined reads. Diagnostics, incomplete coverage and raw continuation remain visible through empty selections. Exact owner or shared-layout acquisition ignores the prefix. Matching contract: kinetic-personalizations-user-id-prefix-v1."),
        "classic-customizations" => add("Classic layer and form selection", "Layer name starts with selects native Key1 across all eligible authored Classic layer types. Form name starts with selects native Key2, not the translated screen caption. Both prefixes are literal and case-sensitive; spaces, punctuation and Unicode stay unchanged. Blank selects all eligible values; both controls combine with AND. Epicor returns a broad superset matching the prefix text before any %, _, [, ] or non-ASCII character; Herbert applies the literal prefixes locally and validates identities and Content type/UTF-16 length only for selected definitions. Excluded definitions are neither validated nor reported. Selected owners keep every composite key, complete Content, native XML and readable scripts. Empty selected pages follow raw native continuation. Exact seven-key retrieval ignores both prefixes. Matching contracts: classic-customizations-layer-name-prefix-v1 and classic-customizations-form-name-prefix-v1."),
        "classic-personalizations" => add("Classic user and form selection", "User ID starts with selects native Key1 personalization owners. Form name starts with selects native Key2, not the translated screen caption. Both prefixes are literal and case-sensitive; spaces, punctuation and Unicode stay unchanged. Blank selects all eligible values; both controls combine with AND. Epicor returns a broad superset matching the prefix text before any %, _, [, ] or non-ASCII character; Herbert applies the literal prefixes locally and validates identities and Content type/UTF-16 length only for selected definitions. Excluded definitions are neither validated nor reported. Selected personal owners keep complete Content, native XML, scripts and all composite variants. Empty selected pages follow raw native continuation. Exact seven-key retrieval ignores both prefixes. Matching contracts: classic-personalizations-user-id-prefix-v1 and classic-personalizations-form-name-prefix-v1."),
        "classic-dashboards" => add("Classic dashboard selection", "Dashboard ID starts with is a literal, case-sensitive DefinitionID prefix. Spaces, punctuation and Unicode stay unchanged. Blank selects all eligible dashboards. Herbert validates the entire inventory before selecting full composite identities, then reads complete selected native graphs and required exact variants. Referenced BAQ exports come from selected schemas only; the embedding setting and original bytes are preserved. Empty selected pages follow raw native continuation without definition or BAQ reads. Exact five-key acquisition ignores the prefix. Matching contract: classic-dashboards-dashboard-id-prefix-v1."),
        _ => {},
    }
    match category {
        "ud-codes" => add(
            "UD codes JSON output",
            "Herbert reads custom code types and their entries in pages. Both collection modes use direct calls without a helper. Code type ID starts with is a literal, case-sensitive prefix; spaces and all other entered characters are preserved. Blank selects all eligible types. Selection happens locally after the complete native page validates. Every selected type retains all eligible entries and native fields. Native paging continues even when a page has no matching type. Exact UDCodeType identity retrieval ignores this discovery filter. A valid zero-match discovery is an empty selection. Matching contract: ud-codes-code-type-id-prefix-v1. Herbert saves one JSON file per selected code type. These files preserve definitions for inspection and history. They are not native import packages, and Herbert does not restore them to Epicor.",
        ),
        "ud-schema" => add(
            "UD schema and mapping JSON",
            "Herbert reads schema and mapping definitions through native services. Both modes use direct reads without a helper. Definition family chooses Schema tables, UD mappings, or Schema tables and all UD mappings (default). Schema table ID starts with is a literal, case-sensitive DataTableID prefix; spaces and Unicode are preserved. Blank includes all eligible schema tables. Mappings are independent of this prefix: the combined choice includes all eligible UD mappings. The prefix remains saved when switching families. Herbert validates all acquired rows before selecting complete graphs; empty selected pages follow native continuation. Exact identities ignore both discovery settings. Matching contracts: ud-schema-definition-family-v1 and ud-schema-schema-table-id-prefix-v1. Dictionary tables use global SystemCode and DataTableID identities. Mappings retain integer MapTableID and company or global scope. JSON preserves custom roots and authored children. Stock parents retain only keys when their custom children need context. Native UDMapColumn children need no Company field. The editable default is 500 parent rows per request. These JSON files are not native import packages. Restoring them to Epicor has not been tested.",
        ),
        "extended-properties" => add(
            "Global extended-property JSON",
            "Server-assisted uses one required temporary ReadAllProperties helper. Direct only refuses this collection before helper installation. The helper reads all global dictionary overrides in one complete response. Table ID starts with is a literal, case-sensitive DataTableID prefix; spaces and Unicode are preserved. Blank includes all eligible tables. Herbert validates every returned field/property graph before selecting complete tables locally. Selection does not reduce the helper read. Exact identity retrieval ignores the discovery prefix and still reads the complete helper response. Matching contract: extended-properties-table-id-prefix-v1. A valid zero-match discovery is a successful empty selection. Herbert writes one JSON file per selected SystemCode and DataTableID. Files preserve field overrides, property values, binding fields and explicit empty overrides. Empty strings are data. The result is not a native import package. Restoring it to Epicor has not been tested. The host tracks helper cleanup. Review cleanup diagnostics before retrying a failed run.",
        ),
        "access-and-assignments" => add("Access definitions and assignments", "Choose Access family for all access, complete security definitions, all three user-assignment projections, or API-key scope assignments. User ID starts with is a literal case-sensitive UserID prefix on user projections only, preserving every character; blank selects all eligible users. Security definitions and API-key assignments remain independent of that prefix. Exact native retrieval ignores discovery controls. The user-assignment reads are narrowed to user IDs starting with the prefix text before any %, _, [, ] or non-ASCII character; the literal prefix is applied locally and only selected assignments are validated. Paging identity checks still cover every returned row, and settings persist through resume. Herbert downloads complete native security graphs and explicit user, company, external-company and API-key assignment projections, then constructs files locally. Global and shared records retain their stored company. Custom permissions beneath system parents retain exact dependency keys without copying the parent. Access scopes include locally built native EAS import archives when their graph is complete. Passwords, key material, contact information and personal settings are excluded from assignment requests. Native authorization still applies; denied surfaces report incomplete results while independent collection continues. Restore assignments only into existing users and API keys that you have checked. No helper or security grant is used."),
        "programs-and-extensions" => add(
            "Program metadata and original binaries",
            "Definition family selects complete services, DataSets, extension sets, external assemblies or all (default). Definition ID starts with is a literal, case-sensitive ClassName, DataSetID, ExtensionSetID or external Name prefix; blank selects all. Complete acquired metadata/supplements validate before selection; only selected binary owners are downloaded. Exact acquisition ignores discovery settings. Direct preserves useful native coverage with explicit missing helper metadata; Assisted permits its existing read-only supplement. Original DLL/PDB bytes, mappings and schema relationships remain separate from native import or execution proof. Missing registered assembly remains partial even with symbols.",
        ),
        "report-definitions" => add(
            "Report definition recovery",
            "Definition family selects report data definitions, BAQ reports, or both. Definition ID starts with is a literal, case-sensitive native RptDefID or BAQRptID prefix; blank selects all. Unselected families are not read. The parent read is narrowed to IDs starting with the prefix text before any %, _, [, ] or non-ASCII character; the literal prefix is applied locally and only selected definitions are validated. Selected-empty pages continue. Complete selected children and query-field occurrences remain together. Exact collection ignores discovery settings. Herbert builds native report-definition XML locally; both modes use direct reads. The editable default remains 50. Native recovery does not prove report execution.",
        ),
        "report-styles-and-layouts" => add(
            "Report layouts and stored packages",
            "Report ID starts with selects complete native-visible custom styles before physical reads. Stored package path starts with independently selects current and historical packages by full PrintProgram. Both prefixes are literal and case-sensitive; blank selects all. Required layouts, subreports and images remain with selected styles even outside the package prefix. Epicor narrows retained-version reads to paths starting with the prefix text before any %, _, [, ] or non-ASCII character; Herbert applies the literal prefix locally and validates only selected stored packages. Excluded packages are neither validated nor reported. Exact collection ignores discovery settings. Direct reads deployed layouts with ExportSsrsRdl; Assisted uses ReadLayouts and can read current stored packages. History remains independent. Invalid stored originals remain .bin evidence with diagnostics. The editable default remains 100. Native recovery does not prove rendering, printing or business behavior.",
        ),
        "report-behavior" => add(
            "Saved report routing and breaking",
            "Report ID starts with selects complete eligible native-visible behavior styles before physical reads. This is a literal, case-sensitive prefix; blank selects all. Each selected style retains all rules, including disabled rules, saved widget bodies and native style context. Raw pages continue through empty selections. Exact collection ignores discovery settings. Both modes read this graph directly. The editable default remains 100. Native persistence and widget serialization do not prove print, mail, delivery or business execution. Source JSON remains evidence when a native file is incomplete.",
        ),
        "configurators" => add(
            "Configurator packages and source-only evidence",
            "Definition family selects configurators, lookups, independent persisted rule/variable source, or all (default). Definition ID starts with is a literal, case-sensitive ConfigID or LookupTblID prefix; blank selects all. Independent Company+SysRowID persisted sources are unaffected by that prefix. Complete selected graphs and required resources remain together; acquired errors and raw continuation remain. Exact acquisition ignores discovery settings. Both modes collect without a helper. Native export remains a fallback for method-rule eligibility, signing and unresolved app ownership. Restoration needs matching part/BOM prerequisites. Audit/history/attachment references remain source-only. Native format proof does not establish business execution.",
        ),
        "business-rules-and-mappings" => add(
            "Business rule files and restore prerequisites",
            "Definition family selects forms, Structured Output, posting rules, or all (default). Definition ID starts with is a literal, case-sensitive FormId or RptStructuredOutputDefID prefix; blank selects all. Complete integer ACTTypeUID posting graphs are independent of that prefix. Forms and Structured Output discovery reads ask the server for a broad LIKE superset matching the prefix text before any %, _, [, ] or non-ASCII character; Herbert applies the literal prefix locally and validates only selected definitions. Posting graphs validate in full; raw continuation remains. Exact acquisition ignores discovery settings. Both modes use pure reads without a helper. Forms/Structured Output default to 100 rows; posting reads the complete company graph independently. Restore forms with UpdateExt, Structured Output with the explicit request preserving date-shaped constants, and posting XML with ImportFromXML. Native projections and prerequisites remain separate from original source JSON.",
        ),
        "custom-resources" => add(
            "Custom resources and native recovery",
            "Resource family selects themes and standalone overrides, the complete translation library, the complete image library, customization FileStore resources, or all (default). No child-ID prefix is applied to aggregate libraries. Acquired errors and native completion remain truthful through empty/resumed output. Both modes use direct reads without a helper. FileStore All is a distinct shared-company sentinel; original bytes require an admitted customization owner. Restore requests remain separate from source values. Image restoration must rebind destination FileStore IDs. Some translation source has no tested import route. Exact identity acquisition remains unsupported.",
        ),
        "solutions-and-packages" => add(
            "Solution history and retained package backups",
            "Definition family selects solution definitions, independent solution types, retained installed packages or all (default). Solution ID starts with is a literal, case-sensitive SolutionID prefix independently applied to persisted headers and retained package catalog owners; blank selects all. Standalone custom types are unaffected. Selected solutions retain complete membership/tracker/required type context. Full acquired graphs/catalogs validate before selection; only selected packages are read. Exact acquisition ignores discovery settings. JSON preserves history and is not an import file. Original retained native ZIP bytes are the recovery artifact. Collection never builds/installs a solution or activates tracking.",
        ),
        "searches-and-navigation" => add(
            "Search and navigation recovery",
            "Herbert preserves search definitions and context menus through direct reads in both modes. No helper is required. The editable default is 1000 parent definitions per request. Native search XML needs the matching typed DataSet and BO Update contract. These files are not universal file-import packages. Restore complete parent and child keys. New rows need new identities and RowMod A. Existing rows need fresh native revisions. Legacy context graphs require ContextType and CustomLayer prerequisites and the insert order recorded in herbertRestore. Unexpected predictive children remain source JSON evidence without XML recovery support.",
        ),
        "menus-and-launch-definitions" => add(
            "Menu recovery and system snapshots",
            "Herbert builds native MenuDataSet XML and source JSON through direct reads. No helper is required. Custom files use Company and MenuID identity. Restore custom parents before children. Select the target company deliberately. MenuHandler maps custom rows to the selected company. AllCompanies cannot preserve every source CompanyVisibility distinction by itself. The native service chooses visibility from the target tenant. Multi-row system snapshots are not inputs to the single-item MenuHandler. Restore only the documented settings on existing system identities. Referenced applications, reports and security assignments require separate collections. The editable default is 4000 menu rows per request. Restore on tenant-enabled systems has not been tested.",
        ),
        "kinetic-personalizations" => add(
            "Personalization files and owner mapping",
            "Herbert reads saved application, grid, home, option and favorite definitions directly without a helper. The editable default is 100 records per request. Original owner, company, device and full source remain in the backup. ICE 4.3 uses the native Layers ZIP wrapper and retains the saved owner/company; it has no modern destination override arguments. Its limited native field projection needs full source JSON through GenXData.StoreData for omitted fields. Newer versions use Personalizations ZIPs with deliberate destination-user mapping, rights and the base application. The native format is frozen once; an unavailable format keeps source and Content with a diagnostic instead of a guessed ZIP. HomePage, UserOptions and favorites use different native methods. Keep replaceFavorites false unless replacement is intended. Restore favorite folders before items. Kinetic personalizations display names are not Kinetic applications and layers draft bodies; unsaved browser edits cannot be collected. Restore has been tested on ICE 4.3 for application and grid ZIPs with full-field source supplementation, homes with images, home options, favorites and legacy chunked records. Legacy recovery orders original XXXChunk rows by numeric SeqNum before native Gen1 import; Epicor decompresses them into equivalent Content rather than recreating physical chunks. Image identities need explicit mapping. Multitenant restore and the native UI import screen have not been tested.",
        ),
        "kinetic-applications-and-layers" => add(
            "Kinetic packages and separate draft recovery",
            "Herbert builds MetaFX ZIPs from complete saved definitions. Current definitions use direct reads in both modes without a helper. Include version history defaults on. Direct only uses native history reads. Server-assisted permits a temporary read-only history helper. Disabling history retains current published files and saved drafts. The editable defaults are 100 application/body rows and 1000 metadata rows. A combined application-and-layers import requires deliberate Overwrite selection, even into an empty target. Preserve the destination before replacement. Application drafts and designer records require separate recovery. Shared custom records use exact seven-key GenXData restoration. A ZIP import alone does not restore all editor work. Unsaved browser edits cannot be collected.",
        ),
        "classic-dashboards" => add(
            "Classic dashboard recovery",
            "Herbert builds native DBD DiffGram files from saved definitions. Both modes use direct reads without a helper. The editable default is 16 dashboard definitions per request. Embed referenced BAQs defaults on. Without embedded BAQs, the destination needs the referenced queries. A failed dependency leaves useful definition evidence and a diagnostic. Native restoration reads the typed DashboardDataSet and saves it with DashBoardSvc.StoreData. Ordinary Update is unsupported. Restore identity includes Company, ProductID, GlbCompany, CGCCode and DefinitionID. Deployed assembly bytes are a separate supplement. DBD files do not include external DLLs or unsaved changes. Native format tests do not prove Classic UI import or restored dashboard execution.",
        ),
        "classic-personalizations" => add(
            "Classic personalization backups",
            "Herbert downloads saved Classic personalizations in complete pages and builds native personalization XML files on this computer. The next page downloads while the current page is processed. Each owner, form, parent layer and country variant keeps its full identity. Filenames follow Epicor's FormName_UserID.xml rule. The original definition is also retained as JSON. No helper is uploaded. The Classic personalization import screen applies a file to the signed-in user; it does not restore every original owner automatically. Unsaved screen changes are not stored on the server and cannot be collected.",
        ),
        "classic-customizations" => add(
            "Classic customization recovery",
            "Herbert builds native Gen3 XML and preserves source JSON and readable scripts. Both modes use direct reads without a helper. The effective editable default is 100 customizations per request. Both are page sizes, not collection limits. Exact identities retain Company, ProductID, TypeCode, CGCCode, Key1, Key2 and Key3. Import the XML through the native Classic customization importer in the intended destination context. Base applications, referenced DLLs and native permissions remain prerequisites. DLL references do not include the DLL bytes. Unsaved client changes cannot be collected. Multitenant restore has not been tested.",
        ),
        "baqs-and-ubaqs" => {
            add("Query ID selection", "Query ID starts with is a literal, case-sensitive prefix for both BAQs and UBAQs. Spaces, punctuation and Unicode are preserved without normalization. Blank selects all eligible query roots. The query read is narrowed to IDs starting with the prefix text before any %, _, [, ] or non-ASCII character; Herbert selects complete queries and every owned child locally and validates only selected queries. Selected queries retain their diagrams, XT/PT dependencies and associated DQ workflows; optional compiled capture includes selected UBAQ owners only. An empty selected page follows native continuation. A valid zero-match discovery is a successful empty selection. Exact identity retrieval remains unsupported for BAQs and UBAQs. Example: queryIdPrefix EXAMPLE selects IDs beginning exactly with EXAMPLE. Matching contract: baqs-and-ubaqs-query-id-prefix-v1.");
            add(
            "BAQ and UBAQ packages",
            "Herbert reads query definitions, diagrams and UBAQ workflows in pages. It builds native BAQ packages locally. Ordinary collection uses no helper. Optional compiled UBAQ capture requires a temporary read-only helper and a matching optional build. Both compiled options default off. Direct only retains ordinary files when optional capture is unavailable. Original compiled bytes remain under Herbert Data/raw. Retain the whole backup and its journal. Reconstructed projects are supplementary evidence and may not build. The editable default is 100 query headers per request. Child rows determine response size. Selected-identity acquisition is unsupported. Use the paged backup route. Native recovery uses the BAQ file. Restore of XT-backed queries has had limited testing; restore of PT-backed queries and extension infrastructure has not been tested. Protected workflows can limit readable source.",
            );
        }
        "bpm-directives" => {
            add("Method and table selection", "Directive family chooses Method and data directives (default), Method directives, or Data directives. Method or table code starts with is a literal, case-sensitive prefix of the full native BpMethodCode, such as Ice.BO.X.Update or Ice.UD39.Update. Spaces, punctuation and Unicode are preserved without normalization. Blank selects all eligible owners in the chosen families. The owner read is narrowed to codes starting with the prefix text before any %, _, [, ] or non-ASCII character; Herbert selects complete method/table groups locally and validates only selected owners. An empty selected page follows native continuation. Every selected DB owner keeps both standard and in-transaction directives. Exact global BO/DB acquisition ignores both discovery settings. Optional compiled contexts and selectors contain selected owners only, after normal output. A valid zero-match discovery is a successful empty selection. Required native dependency packages retain the native service/table scope and can include eligible sibling methods; the prefix selects output owners, not every byte inside such a package. Matching contracts: bpm-directives-directive-family-v1 and bpm-directives-method-code-prefix-v1.");
            add("BPM directive packages", "Herbert reads BO method directives and DB data directives. It builds native BPM files locally when definitions are sufficient. Holds, forms and unreadable workflows require the native export route. An unavailable dependency package leaves incomplete coverage. Readable definitions remain useful evidence. Ordinary collection uses no helper and does not execute directives. The effective editable default is 100 methods per request. These values are not collection limits. Native import uses an explicit destinationGroup. An empty destinationGroup clears the group. On Kinetic 2026.1 the native importer refused data-directive packages, including Epicor's own exports, so data-directive restore on that version is not confirmed.");
            if cfg!(feature = "ordinary-bpm-compiled") {
                add("Optional compiled BPM evidence", "Both compiled options default off. Project creation also selects binary capture. Server-assisted permits the temporary scoped read helper. Direct only preserves ordinary output and reports the optional gap. Original DLL/PDB bytes remain under Herbert Data/raw. Retain the whole backup, including its run journal and association context. Projects remain under the owning method or table. Data-trigger assemblies contain both directive types. Stored bytes do not prove current compilation freshness. Reconstructed projects may lack references and may not build. Native recovery uses the BPM package and persisted workflow.");
            }
        }
        "functions" => {
            add("Library ID selection", "Library ID starts with is a literal, case-sensitive prefix. Spaces, punctuation and Unicode are preserved without normalization. Blank selects all eligible library roots. Herbert validates native inventory before selecting IDs locally and reading complete selected libraries in bulk. Functions, signatures, references, mappings, bodies and other native content stay with their library; referenced libraries remain separate destination prerequisites. Native continuation survives an empty selected page, without a GetLibraries read for that page. Exact global EfxLibrary retrieval ignores the discovery prefix; processing options still apply. Optional compiled owners are selected libraries only. A valid zero-match discovery is a successful empty selection. Example: libraryIdPrefix EXAMPLE selects IDs beginning exactly with EXAMPLE. Matching contract: functions-library-id-prefix-v1.");
            add(
            "Function native files and optional compiled evidence",
            "Herbert reads library definitions in bulk and builds native EFXJ and EFXB files locally. Both current modes use this ordinary route without a helper. Readable code is derived output. Native recovery uses the EFX files, including authored code and widget bodies. Exact retrieval uses global EfxLibrary identity with LibraryID. Company mappings remain library content. The editable default is 100 libraries per request. All pages are collected. Optional compiled capture requires a matching host, feature-enabled Functions and companion composition where applicable. Its settings default off. Server-assisted permits its scoped reader. Direct only retains ordinary output and reports the requested optional gap. Reconstructed C# is supplementary evidence and may not build.",
            );
        }
        "automation-and-integrations" => add(
            "Sensitive values",
            "Automation family selects all automation or one complete System Agent/schedules, Process Set, Message Template or Global Alert family. There is no ID-prefix box: the native partial fallback is a whole-family graph; use exact native retrieval for root precision. Exact retrieval ignores this discovery control. The Automation and integrations plugin reads native service-visible configuration, validates complete acquired graphs before local family selection and builds recovery candidates locally. Settings and acquired diagnostics survive prepared/bulk/legacy resumes; excluded acquired failures remain incomplete. Unknown native fields and original scope are preserved. Sensitive values stay intact by default; enable the saved filter to project declared password, secret, API key and token values as null with explicit omission metadata. System and execution-history exclusions apply independently. Useful native source evidence survives a denied richer read and is labeled partial. Process tasks use definition-only SaveProcessTask recovery, never submission or execution.",
        ),
        "configuration-references" => add(
            "References",
            "References come from definitions already collected by other modules, including explicit table declarations in JSON, JSONC and XML. Names, source scope and provenance are preserved. View-table declarations are distinguished from database declarations. Missing or unparsed producer content is reported; collection does not execute queries or follow references into business rows.",
        ),
        _ => {
            if matches!(category, "kinetic-applications-and-layers" | "kinetic-personalizations") {
                add(
                    "Kinetic scopes",
                    "Supported Kinetic definitions and personalizations retain their company, global or user scope and owner.",
                );
            }
        }
    }
    sections
}
